-lg bg-emerald-700 px-2 py-1 text-xs font-semibold text-white">Bayar</button></form><form method="POST" action="{{ route('payroll.cancel', $payroll) }}" class="inline" onsubmit="return confirm('Batalkan draft payroll ini?')">@csrf<button class="ml-1 text-xs text-rose-700">Batal</button></form>@elseif($payroll->status === 'PAID')<a href="{{ route('expenses.index', ['q' => $payroll->expense?->kode_beban]) }}" class="text-xs font-semibold text-blue-700">Lihat beban</a>@else<span class="text-xs text-slate-400">—</span>@endif</td></tr>@empty<tr><td colspan="8" class="px-4 py-10 text-center text-slate-500">Belum ada payroll.</td></tr>@endforelse</tbody></table>@if($payrolls->hasPages())<div class="border-t p-4">{{ $payrolls->links() }}</div>@endif</section>
